(() => {
  'use strict';
  const E=window.ValuationEngine,$=s=>document.querySelector(s),main=$('#main');
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=(n,full=false)=>full?'₹'+Math.round(n).toLocaleString('en-IN'):n>=1e7?'₹'+(n/1e7).toFixed(2)+' Cr':'₹'+(n/1e5).toFixed(2)+' L';
  const num=n=>Number(n).toLocaleString('en-IN');
  const date=d=>new Date(d).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'});
  const disclaimer='Property prices shown by this application are AI-generated estimates based on available data and user-provided information. They are not guaranteed valuations, professional appraisals, or financial advice.';
  let storageAvailable=true;
  function read(key,fallback){try{const value=localStorage.getItem('dwelliq-'+key);return value?JSON.parse(value):fallback;}catch{storageAvailable=false;return fallback;}}
  function write(key,value){try{localStorage.setItem('dwelliq-'+key,JSON.stringify(value));return true;}catch{storageAvailable=false;toast('Browser storage is unavailable or full. This change lasts for this session.');return false;}}
  let history=read('history',[]);if(!Array.isArray(history)) history=[];
  history=history.filter(r=>r&&Number.isFinite(r.price)&&r.property&&Array.isArray(r.factors)&&!E.validate(r.property).length).slice(0,100);
  let profile=read('profile',{name:'Jamie Davis',city:'Bengaluru',persist:true});
  if(!profile||typeof profile.name!=='string')profile={name:'Jamie Davis',city:'Bengaluru',persist:true};
  if(!E.cities[profile.city])profile.city='Bengaluru';
  let activity=read('activity',[]);if(!Array.isArray(activity))activity=[];
  let errors=read('errors',[]);if(!Array.isArray(errors))errors=[];
  let bookmarks=read('bookmarks',[]);if(!Array.isArray(bookmarks))bookmarks=[];
  let marketCity=profile.city,chartPeriod='1Y',adminPeriod=7,step=0,route='home',busy=false,toastTimer;
  const defaultProperty={country:'India',state:'Karnataka',city:'Bengaluru',locality:'Whitefield',pin:'560066',landmark:'',type:'Apartment',bedrooms:3,bathrooms:2,balconies:1,area:1450,builtup:1300,carpet:1100,floor:4,floors:12,age:3,parking:'Yes',furnishing:'Semi-furnished',amenities:['Security','Lift','Garden'],condition:'Good'};
  let draft={...defaultProperty,amenities:[...defaultProperty.amenities]},current=E.predict(defaultProperty),simulation=null;
  function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
  function logError(error){errors.unshift({date:new Date().toISOString(),message:String(error.message||error).slice(0,300)});errors=errors.slice(0,20);write('errors',errors);}
  function record(type,detail){activity.unshift({type,detail,date:new Date().toISOString()});activity=activity.slice(0,60);write('activity',activity);}
  try{E.setRates(read('rates',{}));}catch(e){logError(e);}
  function setTheme(theme){document.body.classList.toggle('dark',theme==='dark');$('#theme-toggle').textContent=theme==='dark'?'☀':'☾';$('#theme-toggle').setAttribute('aria-label',theme==='dark'?'Switch to light mode':'Switch to dark mode');write('theme',theme);}
  setTheme(read('theme','light'));
  const nav=[['home','Overview','▦'],['predict','Predict price','⌂'],['market','Market insights','↗'],['history','My predictions','◷'],['profile','Profile','♙']];
  $('#navigation').innerHTML=nav.map(([id,label,icon])=>`<a class="nav-link" href="#${id}" data-nav="${id}" aria-label="${label}"><span class="nav-icon" aria-hidden="true">${icon}</span><span>${label}</span></a>`).join('');
  function refreshName(){const name=profile.name.trim()||'Jamie Davis',initials=name.split(/\s+/).slice(0,2).map(n=>n[0]).join('').toUpperCase();$('#sidebar-name').textContent=name;document.querySelectorAll('.avatar').forEach(el=>el.textContent=initials);}
  refreshName();$('#year').textContent=new Date().getFullYear();
  function options(items,selected){return items.map(v=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(v)}</option>`).join('');}
  function field(label,name,value,type='text',extra=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
  function selectField(label,name,items,selected,extra=''){return `<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}" ${extra}>${options(items,selected)}</select></div>`;}
  function heading(title,subtitle,actions='',eyebrow='PROPERTY INTELLIGENCE'){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="heading-subtitle">${subtitle}</p></div>${actions}</div>`;}
  function info(text='This is an interactive sample experience. Rates, trends, listings, and estimates are illustrative; no live market feed or trained AI model is connected.'){return `<div class="info-strip"><span aria-hidden="true">ⓘ</span><p>${text}</p></div>`;}
  function stat(label,value,sub,icon='↗'){return `<article class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon" aria-hidden="true">${icon}</span></div><strong class="stat-value">${value}</strong><p class="stat-bottom">${sub}</p></article>`;}
  const listingNames=['The Greenview Residences','Oakwood Park Apartments','The Willow House'];
  function comparables(p=current.property){const c=E.cities[p.city],baseRate=E.getRate(p.city)*(Object.hasOwn(c.areas,p.locality)?c.areas[p.locality]:1);return [0.95,1.08,1.17].map((mult,i)=>{const area=Math.round(Number(p.area)*[.9,1.05,1.16][i]/10)*10,rate=Math.round(baseRate*mult);return {id:p.city+'-'+p.locality+'-'+i,name:listingNames[i],city:p.city,locality:p.locality,type:p.type,bedrooms:p.type==='Plot/Land'?0:Math.max(1,Number(p.bedrooms)+(i===2?1:0)),area,price:area*rate,rate,distance:[1.2,2.4,3.1][i],image:`assets/property-${i+1}.jpg`};});}
  function propertyCards(p=current.property){return `<div class="property-grid">${comparables(p).map((l,i)=>`<article class="property-card"><div class="property-image"><img src="${l.image}" alt="${['Modern home with a peaceful garden','Bright contemporary property interior','Modern residence with outdoor space'][i]}" loading="lazy"><span class="property-badge">Sample · ${esc(l.type)}</span><button class="bookmark" data-bookmark="${i}" aria-label="${bookmarks.includes(l.id)?'Unsave':'Save'} ${esc(l.name)}" aria-pressed="${bookmarks.includes(l.id)}">${bookmarks.includes(l.id)?'♥':'♡'}</button></div><div class="property-body"><h3>${esc(l.name)}</h3><p class="property-location">⌖ ${esc(l.locality)}, ${esc(l.city)}</p><div class="property-details"><span>⌂ ${l.bedrooms?l.bedrooms+' beds':'Land plot'}</span><span>▱ ${num(l.area)} sq.ft</span><span>⌖ ${l.distance} km away</span></div><div class="property-price"><div><strong>${money(l.price)}</strong><small>₹${num(l.rate)} / sq.ft</small></div><button data-listing="${i}">View details ↗</button></div></div></article>`).join('')}</div>`;}
  function trendValues(city,period=chartPeriod){const rate=E.getRate(city),growth=E.cities[city].growth,months=period==='6M'?6:period==='3Y'?36:12;return Array.from({length:7},(_,i)=>Math.round(rate/(1+growth/100)**((months/12)*(1-i/6))*(1+[0,.008,-.005,.009,-.003,.003,0][i])));}
  function lineChart(city){const values=trendValues(city),min=Math.min(...values)*.98,max=Math.max(...values)*1.02;const pts=values.map((v,i)=>[45+i*67,135-(v-min)/(max-min)*105]);const path=pts.map((p,i)=>(i?'L':'M')+p.join(',')).join(' ');const labels=chartPeriod==='6M'?['May','Jun','Jul','Aug','Sep','Oct','Now']:chartPeriod==='3Y'?['2023','','2024','','2025','','2026']:['Nov','Jan','Mar','May','Jul','Sep','Now'];return `<div class="chart" data-city="${city}"><div class="chart-tip" hidden></div><svg viewBox="0 0 490 165" role="img" aria-label="Illustrative ${city} price trend over ${chartPeriod}"><defs><linearGradient id="chart-gradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#689f75" stop-opacity=".2"/><stop offset="100%" stop-color="#689f75" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>{const y=27+i*36;return `<line class="chart-grid" x1="45" y1="${y}" x2="461" y2="${y}"/><text x="0" y="${y+3}">${((max-(max-min)*(y-30)/105)/1000).toFixed(1)}k</text>`;}).join('')}<path d="${path} L447,140 L45,140 Z" fill="url(#chart-gradient)"/><path class="chart-line" d="${path}"/>${pts.map(([x,y],i)=>`<g><circle cx="${x}" cy="${y}" r="12" fill="transparent" tabindex="0" data-chart-point="${values[i]}" aria-label="${labels[i]||'Period '+(i+1)}: ${values[i]} rupees per square foot"><title>${labels[i]}: ₹${num(values[i])}/sq.ft (sample)</title></circle><circle cx="${x}" cy="${y}" r="${i===6?4:2}" fill="var(--green)" pointer-events="none"/><text x="${x}" y="161" text-anchor="middle">${labels[i]}</text></g>`).join('')}</svg></div>`;}
  function trendCard(city=marketCity){return `<article class="card"><div class="card-heading"><div><h2>Market pulse</h2><p class="card-subtitle">A little perspective on your local market.</p></div><label class="sr-only" for="market-city">Market city</label><select id="market-city" class="select-compact">${options(Object.keys(E.cities),city)}</select></div><div class="chart-topline"><strong class="chart-price">₹${num(E.getRate(city))}<small> / sq.ft</small></strong><span class="positive-badge">↗ ${E.cities[city].growth}%</span></div>${lineChart(city)}<div class="chart-footer"><span><i class="legend-dot"></i> Average price / sq.ft · sample</span><div class="segment-control" aria-label="Chart period">${['6M','1Y','3Y'].map(v=>`<button data-period="${v}" class="${v===chartPeriod?'active':''}" aria-pressed="${v===chartPeriod}">${v}</button>`).join('')}</div></div></article>`;}
  function renderHome(){main.innerHTML=heading(`A smarter move starts here<span class="positive">.</span>`,'Understand your property. Explore its potential.',`<button class="button" data-route="history">◷ My predictions</button>`,'YOUR HOME, BETTER UNDERSTOOD')+`<section class="hero"><div class="hero-content"><span class="hero-badge">✧ A LITTLE INTELLIGENCE. A LOT OF CLARITY.</span><h2>Your home has a story.<br>Know what <em>it’s worth.</em></h2><p>Predict your property’s value with AI-inspired insights.<br>Less guesswork. More confidence in your next move.</p><div class="button-row"><button class="button light" data-route="predict">Predict House Price <span>↗</span></button><button class="button hero-secondary" data-route="market">Explore Market Insights <span>→</span></button></div></div><span class="hero-image-label">Spaces worth dreaming about</span><div class="hero-float"><span class="float-icon">⌂</span><div><strong>Every home. A new possibility.</strong><small>Your next chapter begins with clarity.</small></div></div></section><section class="stats-grid" aria-label="Sample overview statistics">${stat('Properties in sample dataset','12,480','<span class="positive">↗ 12.8%</span> sample annual growth','▦')}${stat('Average sample estimate','₹86.4 L','Across the illustrative property collection','⌂')}${stat('Prediction accuracy','Unmeasured','Sample engine · no validation dataset','◎')}${stat('Market trend','+'+E.cities[marketCity].growth+'%','<span class="positive">↗ Increasing</span> · illustrative YoY','↗')}</section><div class="dashboard-grid">${trendCard()}<article class="card quick-estimate"><span class="quick-icon">✧</span><h2>Meet your property’s potential.</h2><p>Start with a few details.<br>We’ll help you see the bigger picture.</p><form id="quick-form"><div class="form-grid">${selectField('City','quick-city',Object.keys(E.cities),profile.city)}${field('Total area (sq.ft)','quick-area',1450,'number','min="100" max="100000" required')}${selectField('Bedrooms','quick-beds',['1','2','3','4','5'],'3')}</div><button class="button primary" type="submit">Get my estimate <span>↗</span></button><p class="mini-disclaimer">Free to explore. No account required.</p></form></article></div><section><div class="section-heading"><div><h2>Around your neighbourhood</h2><p>A closer look at comparable spaces in ${esc(current.property.locality)}.</p></div><button class="text-link" data-route="market">Explore properties <span>↗</span></button></div>${propertyCards()}</section>${info()}`;}
  function summary(){return `<aside class="card form-summary"><h3>Your property, at a glance</h3><img class="summary-image" src="assets/property-1.jpg" alt="A contemporary home surrounded by greenery"><div class="summary-line"><span>Location</span><strong>${esc(draft.city)}</strong></div><div class="summary-line"><span>Neighbourhood</span><strong>${esc(draft.locality)}</strong></div><div class="summary-line"><span>Property</span><strong>${esc(draft.type)}</strong></div><div class="summary-line"><span>Area</span><strong>${num(draft.area)} sq.ft</strong></div><div class="summary-line"><span>Bedrooms</span><strong>${draft.type==='Plot/Land'?'Not applicable':esc(draft.bedrooms)}</strong></div><div class="summary-line"><span>Amenities</span><strong>${draft.amenities.length} selected</strong></div>${info('Your entries stay in this browser. Estimates use illustrative city rates, with a wider range for unlisted localities.')}</aside>`;}
  function renderPredict(error=''){const labels=['Location','Details','Features','Condition'];let body='';
    if(step===0)body=`<div class="form-intro"><h2>Let’s find your neighbourhood.</h2><p>A good estimate starts with the right location. This sample supports eight Indian cities.</p></div><div class="form-grid">${selectField('Country','country',['India'],draft.country)}${selectField('State','state',[...new Set(Object.values(E.cities).map(c=>c.state))],draft.state)}${selectField('City','city',Object.keys(E.cities).filter(c=>E.cities[c].state===draft.state),draft.city)}<div class="field"><label for="locality">Locality / area</label><input name="locality" id="locality" list="locality-list" value="${esc(draft.locality)}" maxlength="100" required><datalist id="locality-list">${options(Object.keys(E.cities[draft.city].areas),draft.locality)}</datalist><small>Unlisted localities use the city’s sample average.</small></div>${field('PIN code','pin',draft.pin,'text','pattern="[1-9][0-9]{5}" inputmode="numeric" maxlength="6" required')}${field('Nearby landmark (optional)','landmark',draft.landmark,'text','maxlength="100"')}</div><div class="inline-notice" style="margin-top:22px;margin-bottom:0">⌖ ${esc(draft.city)}, ${esc(draft.state)} · Location analysis uses the selected city and locality. No live map is connected.</div>`;
    if(step===1)body=`<div class="form-intro"><h2>The details make a difference.</h2><p>Tell us about the space. All area measurements are in square feet.</p></div><div class="form-grid three">${selectField('Property type','type',E.types,draft.type)}${field('Bedrooms','bedrooms',draft.bedrooms,'number',`min="${draft.type==='Plot/Land'?0:1}" max="20" required`)}${field('Bathrooms','bathrooms',draft.bathrooms,'number',`min="${draft.type==='Plot/Land'?0:1}" max="20" required`)}${field('Balconies','balconies',draft.balconies,'number','min="0" max="20" required')}${field('Total area (sq.ft)','area',draft.area,'number','min="100" max="100000" required')}${field('Built-up area (sq.ft)','builtup',draft.builtup,'number',`min="${draft.type==='Plot/Land'?0:50}" max="100000" required`)}${field('Carpet area (sq.ft)','carpet',draft.carpet,'number',`min="${draft.type==='Plot/Land'?0:50}" max="100000" required`)}${field('Floor number','floor',draft.floor,'number','min="0" max="150" required')}${field('Total floors','floors',draft.floors,'number',`min="${draft.type==='Plot/Land'?0:1}" max="150" required`)}${field('Property age (years)','age',draft.age,'number','min="0" max="150" required')}${selectField('Parking availability','parking',['Yes','No'],draft.parking)}${selectField('Furnishing','furnishing',['Unfurnished','Semi-furnished','Furnished'],draft.furnishing)}</div>${draft.type==='Plot/Land'?info('Land estimates ignore bedrooms, floors, building condition, furnishing and building amenities. Nearby facilities still apply.'):''}`;
    if(step===2)body=`<div class="form-intro"><h2>A little more to love.</h2><p>Select the amenities and nearby facilities your property offers.</p></div><div class="feature-grid">${E.amenities.map(a=>`<label class="feature"><input type="checkbox" name="amenities" value="${esc(a)}" ${draft.amenities.includes(a)?'checked':''}><span>${esc(a)}</span></label>`).join('')}</div>`;
    if(step===3)body=`<div class="form-intro"><h2>How is your property looking?</h2><p>Condition helps us account for the space’s current state.</p></div><fieldset style="border:0;padding:0;margin:0"><legend class="sr-only">Property condition</legend><div class="condition-grid">${Object.keys(E.conditions).map((c,i)=>`<label class="condition-option"><input type="radio" name="condition" value="${c}" ${draft.condition===c?'checked':''} required><span aria-hidden="true">${['✧','◇','⌂','◷','⚒'][i]}</span>${c}<small>${['Freshly built','Like new','Well maintained','Some wear','Work needed'][i]}</small></label>`).join('')}</div></fieldset><div class="inline-notice" style="margin-top:25px">You’re ready to explore your estimate. Your result will include a price range, a factor-by-factor explanation and sample comparable properties.</div>${info('Confidence is an illustrative data coverage indicator, not measured statistical accuracy. An estimate is not a guaranteed selling price.')}`;
    main.innerHTML=heading('A little detail. A clearer value.','Four simple steps to understand your property’s potential.',`<button class="button" data-route="home">← Overview</button>`,'YOUR PROPERTY ESTIMATE')+`<div class="prediction-layout"><section class="card"><div class="stepper" aria-label="Prediction progress">${labels.map((s,i)=>`<div class="step-item ${i===step?'active':i<step?'done':''}" ${i===step?'aria-current="step"':''}><span>${i<step?'✓':i+1}</span>${s}</div>`).join('')}</div><form id="prediction-form">${body}${error?`<div class="form-error" role="alert">${esc(error)}</div>`:''}<div class="form-actions">${step?'<button class="button" type="button" id="step-back">← Back</button>':'<span class="card-subtitle">Step 1 of 4</span>'}<button class="button primary" type="submit">${step===3?'Generate my estimate ✧':'Continue →'}</button></div></form></section>${summary()}</div>`;
  }
  function collectDraft(){const form=$('#prediction-form');if(!form)return;const data=new FormData(form);for(const [key,value]of data){if(key==='amenities')continue;draft[key]=['bedrooms','bathrooms','balconies','area','builtup','carpet','floor','floors','age'].includes(key)?Number(value):value;}if(step===2)draft.amenities=data.getAll('amenities');}
  function savePrediction(r=current,manual=false){if(history.some(x=>x.id===r.id)){if(manual)toast('This prediction is already saved.');return;}const saved={...r,id:r.id||crypto.randomUUID()};r.id=saved.id;history.unshift(saved);history=history.slice(0,100);const persisted=write('history',history);if(manual)toast(persisted?'Prediction saved to your history.':'Prediction saved for this session.');}
  async function generate(){const issues=E.validate(draft);if(issues.length){renderPredict(issues.join(' '));return;}if(busy)return;busy=true;main.innerHTML=heading('Finding your property’s potential.','A few details. A little perspective. A clearer view.')+`<div class="card loading-card" role="status" aria-live="polite"><div class="loading-orbit"></div><h2>Putting the details together…</h2><p class="heading-subtitle">Comparing sample rates and explaining the factors.</p><div class="skeleton"></div><div class="skeleton" style="max-width:160px"></div></div>`;await new Promise(r=>setTimeout(r,1000));try{current=E.predict(draft);simulation=null;step=0;current.id=crypto.randomUUID();record('Prediction',draft.locality+', '+draft.city);if(profile.persist)savePrediction(current);busy=false;if(route==='predict')go('result');else toast('Estimate ready. Open My predictions to view it.');}catch(e){busy=false;logError(e);renderPredict(e.message);}}
  function factors(r){return r.factors.filter(f=>Math.abs(f.percent)>.01).map(f=>`<div class="factor-row"><span>${esc(f.name)}</span><div class="factor-track"><div class="factor-fill ${f.percent<0?'negative':''}" style="width:${Math.min(100,Math.abs(f.percent)*5)}%"></div></div><span class="factor-value ${f.percent<0?'negative':'positive'}">${f.percent>=0?'+':''}${f.percent.toFixed(1)}%</span></div>`).join('');}
  function renderResult(){const r=current,p=r.property;main.innerHTML=heading('Meet your property’s potential.','Your estimate for '+esc(p.locality)+', '+esc(p.city)+'.',`<button class="button" id="edit-property">Edit property ↗</button>`,'THE BIGGER PICTURE')+`<section class="result-hero"><p class="result-overline">Estimated property value · sample</p><div class="result-price" id="animated-price">${money(r.price,true)}</div><p class="result-range">Estimated range ${money(r.min)} — ${money(r.max)}</p><div class="button-row"><button class="button light" id="save-prediction">♡ Save prediction</button><button class="button" id="pdf-report">↓ Download PDF</button><button class="button" id="share-prediction">↗ Share estimate</button><button class="button" id="json-report">↓ Data report</button></div></section><div class="stats-grid">${stat('Estimated price / sq.ft','₹'+num(r.perSqft),'Based on total property area','▱')}${stat('Illustrative confidence',r.confidence+'%','Data coverage · not measured accuracy','◎')}${stat('Market position',r.marketPosition.replace(' sample average',''), 'Compared with sample city rate','↗')}${stat('Prediction date',date(r.date),'Illustrative rules v1 · INR','◷')}</div><div class="result-grid"><article class="card"><h2>Why this price?</h2><p class="card-subtitle">Each change is a percentage of the base value, ${money(r.base)}.<br>Base value = total area × sample city rate.</p>${factors(r)}<p class="metric-note">Area scales the base value directly. These additive adjustments sum to the displayed estimate.</p></article><article class="card"><h2>A closer look at your estimate</h2><div class="donut-wrap"><div class="donut" style="--angle:${r.confidence*3.6}deg"><strong>${r.confidence}%<small>Data coverage</small></strong></div><div class="legend-list"><span><i class="legend-dot"></i> Supported city</span><span><i class="legend-dot"></i> ${Object.hasOwn(E.cities[p.city].areas,p.locality)?'Known sample locality':'City-level sample rate'}</span><span><b>±${Math.round((r.max/r.price-1)*100)}%</b> illustrative range</span></div></div><p class="metric-note">This score describes sample data coverage. It is not a calibrated probability, tested accuracy or professional valuation.</p><div class="summary-line"><span>Property</span><strong>${esc(p.type)}</strong></div><div class="summary-line"><span>Total area</span><strong>${num(p.area)} sq.ft</strong></div><div class="summary-line"><span>Condition</span><strong>${esc(p.condition)}</strong></div><button class="button primary" data-route="simulator" style="width:100%;margin-top:25px">Explore “What if?” →</button></article></div><div class="section-heading"><div><h2>Similar spaces. Useful perspective.</h2><p>Illustrative comparables, not available listings or observed sale prices.</p></div><button class="text-link" data-route="market">Market insights ↗</button></div>${propertyCards(p)}${info(disclaimer+' This version uses sample data and a rules engine; no trained AI is connected.')}`;animatePrice(r.price);}
  function animatePrice(target){const el=$('#animated-price');if(!el||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const start=performance.now();function frame(now){if(!el.isConnected)return;const t=Math.min(1,(now-start)/650);el.textContent=money(target*(.92+.08*(1-(1-t)**3)),true);if(t<1)requestAnimationFrame(frame);}requestAnimationFrame(frame);}
  function renderMarket(){const c=E.cities[marketCity];const marketP={...current.property,city:marketCity,state:c.state,locality:marketCity===current.property.city?current.property.locality:Object.keys(c.areas)[0]};main.innerHTML=heading('See the neighbourhood in numbers.','Explore the patterns behind your property’s potential. Sample market data.',`<button class="button" data-route="predict">New prediction ↗</button>`,'MARKET INSIGHTS')+`<div class="city-grid">${Object.keys(E.cities).map(city=>`<button class="city-card ${city===marketCity?'selected':''}" data-market="${city}" aria-pressed="${city===marketCity}"><h3>${city}</h3><strong>₹${num(E.getRate(city))}<small> / sq.ft</small></strong><span class="positive-badge">↗ ${E.cities[city].growth}% YoY</span></button>`).join('')}</div><section class="stats-grid">${stat('Average sample property',money(E.getRate(marketCity)*1450),'At 1,450 sq.ft · sample benchmark','⌂')}${stat('Demand level',c.demand+' / 100',c.demand>70?'High sample demand':'Moderate sample demand','↗')}${stat('Supply level',c.supply+' / 100','Illustrative relative availability','▦')}${stat('Year-over-year change','+'+c.growth+'%','Illustrative trend · increasing','↗')}</section><div class="dashboard-grid">${trendCard(marketCity)}<article class="card"><h2>Demand meets supply</h2><p class="card-subtitle">Relative indicators for ${marketCity} · sample</p><div class="donut-wrap"><div class="donut" style="--angle:${c.demand*3.6}deg"><strong>${c.demand}<small>Demand index</small></strong></div><div class="legend-list"><span>Demand <b>${c.demand} / 100</b></span><span>Supply <b>${c.supply} / 100</b></span><span>Trend <b class="positive">↗ Increasing</b></span></div></div><p class="metric-note">These sample indicators show how a connected market dashboard could work.</p></article></div><article class="card" style="margin-bottom:24px"><h2>One city, different neighbourhoods.</h2><p class="card-subtitle">Illustrative locality price / sq.ft in ${marketCity}</p><div class="bar-chart">${Object.entries(c.areas).map(([area,m])=>`<div class="bar-column"><span>₹${num(Math.round(E.getRate(marketCity)*m))}</span><div style="--height:${m/1.5*125}px" role="img" aria-label="${esc(area)} sample rate ${Math.round(E.getRate(marketCity)*m)}"></div><small>${esc(area)}</small></div>`).join('')}</div></article><div class="section-heading"><div><h2>Around ${esc(marketP.locality)}</h2><p>Sample comparable properties for your selected city.</p></div></div>${propertyCards(marketP)}${info()}`;}
  function renderSimulator(){simulation=simulation||{...current.property,amenities:[...current.property.amenities]};const p=simulation,plot=p.type==='Plot/Land';main.innerHTML=heading('What if your home could be more?','Change a detail. Explore the difference. All values are illustrative.',`<button class="button" data-route="result">← My estimate</button>`,'THE POSSIBILITY SIMULATOR')+`<div class="sim-layout"><article class="card"><div class="card-heading"><h2>Explore the possibilities</h2><button class="text-link" id="reset-simulator">Reset ↺</button></div><form id="sim-form">${selectField('Location','sim-city',Object.keys(E.cities),p.city)}<div class="range-field"><div class="range-label"><label for="sim-area">Total area</label><strong id="sim-area-value">${num(p.area)} sq.ft</strong></div><input id="sim-area" type="range" min="100" max="${Math.max(5000,current.property.area*2)}" step="50" value="${p.area}"></div><div class="range-field"><div class="range-label"><label for="sim-bedrooms">Bedrooms</label><strong id="sim-bedrooms-value">${p.bedrooms}</strong></div><input id="sim-bedrooms" type="range" min="${plot?0:1}" max="10" value="${p.bedrooms}" ${plot?'disabled':''}></div><div class="range-field"><div class="range-label"><label for="sim-age">Property age</label><strong id="sim-age-value">${p.age} years</strong></div><input id="sim-age" type="range" min="0" max="100" value="${p.age}" ${plot?'disabled':''}></div><label class="toggle-row">Parking availability<input type="checkbox" id="sim-parking" ${p.parking==='Yes'?'checked':''} ${plot?'disabled':''}></label><label class="toggle-row">Swimming pool<input type="checkbox" id="sim-pool" ${p.amenities.includes('Swimming pool')?'checked':''} ${plot?'disabled':''}></label><label class="toggle-row">Renovate to excellent condition<input type="checkbox" id="sim-renovate" ${p.condition==='Excellent'?'checked':''} ${plot?'disabled':''}></label></form>${info('Changing area scales built-up and carpet areas proportionally. Renovation does not change the building’s age. Location changes use the first sample locality in that city.')}</article><article class="card sim-output"><p class="eyebrow">YOUR NEXT POSSIBILITY</p><h2>A small change. A different outlook.</h2><p class="card-subtitle" style="margin-top:20px">Current estimate</p><div class="sim-base">${money(current.price,true)}</div><p class="card-subtitle" style="margin-top:22px">Simulated estimate ↓</p><div id="sim-price" class="sim-price" aria-live="polite"></div><div class="sim-diff" id="sim-diff"></div><div id="sim-factors"></div><button class="button primary" id="save-simulation" style="width:100%;margin-top:25px">Save this possibility ♡</button><p class="metric-note">A comparison of estimates, not a promise of returns. Improvement costs, taxes and selling fees are not included.</p></article></div>`;updateSimulation(false);}
  function updateSimulation(collect=true){if(collect){const old=simulation,city=$('#sim-city').value,area=Number($('#sim-area').value);simulation={...old,city,state:E.cities[city].state,locality:city===old.city?old.locality:Object.keys(E.cities[city].areas)[0],area,builtup:Math.round(current.property.builtup*area/current.property.area),carpet:Math.round(current.property.carpet*area/current.property.area),bedrooms:Number($('#sim-bedrooms').value),age:Number($('#sim-age').value),parking:$('#sim-parking').checked?'Yes':'No',condition:$('#sim-renovate').checked?'Excellent':current.property.condition,amenities:old.amenities.filter(a=>a!=='Swimming pool')};if($('#sim-pool').checked)simulation.amenities.push('Swimming pool');}const r=E.predict(simulation),diff=r.price-current.price;$('#sim-area-value').textContent=num(simulation.area)+' sq.ft';$('#sim-bedrooms-value').textContent=simulation.bedrooms;$('#sim-age-value').textContent=simulation.age+' years';$('#sim-price').textContent=money(r.price,true);$('#sim-diff').textContent=(diff>=0?'+':'−')+money(Math.abs(diff))+' estimated '+(diff>=0?'increase':'decrease');$('#sim-diff').classList.toggle('negative',diff<0);$('#sim-factors').innerHTML=`<div class="summary-line"><span>Price / sq.ft</span><strong>₹${num(r.perSqft)}</strong></div><div class="summary-line"><span>Location</span><strong>${esc(simulation.city)}</strong></div><div class="summary-line"><span>Estimated range</span><strong>${money(r.min)} – ${money(r.max)}</strong></div>`;}
  function renderHistory(){main.innerHTML=heading('Your property journey, in perspective.','Saved estimates stay on this device. Select two to compare.',`<div class="button-row"><button class="button" id="compare-history">Compare selected ⇄</button><button class="button primary" data-route="predict">New estimate +</button></div>`,'MY PREDICTIONS')+(history.length?`<div class="history-list">${history.map(r=>`<article class="history-card"><input class="history-checkbox" type="checkbox" value="${esc(r.id)}" aria-label="Compare ${esc(r.property.locality)} ${date(r.date)}"><span class="history-icon">⌂</span><div><h3>${esc(r.property.locality)}, ${esc(r.property.city)}</h3><p>${esc(r.property.type)} · ${num(r.property.area)} sq.ft · ${date(r.date)}</p></div><div class="history-price"><strong>${money(r.price)}</strong><small>${r.confidence}% illustrative confidence</small></div><button class="button small" data-history="${esc(r.id)}">View ↗</button><button class="icon-button delete-history" data-delete="${esc(r.id)}" aria-label="Delete prediction">×</button></article>`).join('')}</div>`:`<article class="card empty-state"><span>◷</span><h2>Your next chapter starts here.</h2><p>No saved predictions yet.<br>Get an estimate and keep your possibilities in one place.</p><button class="button primary" data-route="predict">Predict House Price ↗</button></article>`)+info(storageAvailable?'History is stored locally in your browser, with a maximum of 100 predictions. Clearing browser data will remove saved estimates.':'Storage is unavailable. Your history is available only during this session.');}
  function renderProfile(){main.innerHTML=heading('Make yourself at home.','Your personal preferences, all in one place.','','YOUR WORKSPACE')+`<div class="profile-layout"><article class="card"><div class="profile-header"><span class="avatar">${esc(profile.name.split(/\s+/).slice(0,2).map(n=>n[0]).join('').toUpperCase())}</span><div><h2>${esc(profile.name)}</h2><p>Local profile · no online account</p></div></div><form id="profile-form"><div class="form-grid">${field('Display name','profile-name',profile.name,'text','maxlength="60" required')}${selectField('Preferred city','profile-city',Object.keys(E.cities),profile.city)}</div><button class="button primary" style="margin-top:24px">Save preferences ✓</button></form>${info('This personal workspace is stored on this device. It is not authentication and should not be used to store sensitive information.')}</article><article class="card"><h2>The little preferences</h2><div class="settings-row"><div>Appearance<small>Switch between light and dark surfaces.</small></div><button class="button small" id="profile-theme">${document.body.classList.contains('dark')?'Light mode ☀':'Dark mode ☾'}</button></div><label class="settings-row"><div>Save estimates automatically<small>Keep each new prediction in local history.</small></div><input id="auto-save" type="checkbox" ${profile.persist?'checked':''} style="accent-color:var(--green)"></label><div class="settings-row"><div>Download your history<small>Export your local predictions as JSON.</small></div><button class="button small" id="export-history">Export ↓</button></div><div class="settings-row"><div>Clear local history<small>Remove saved predictions from this browser.</small></div><button class="button small danger" id="clear-history">Clear</button></div><div class="settings-row" style="border-bottom:0"><div>Sample admin dashboard<small>Inspect analytics and manage local sample rates.</small></div><button class="button small" data-route="admin">Open ↗</button></div></article></div>`;}
  function renderAdminContent(){const total=activity.filter(x=>x.type==='Prediction').length,average=history.length?history.reduce((s,r)=>s+r.price,0)/history.length:0,metrics=read('metrics',null);const counts=Object.keys(E.cities).map(city=>({city,count:history.filter(r=>r.property.city===city).length})).sort((a,b)=>b.count-a.count);main.innerHTML=heading('Behind the insight.','Local analytics for this browser’s sample experience.',`<button class="button" id="export-dataset">Export sample rates ↓</button>`,'DEMO ADMIN DASHBOARD')+`<div class="inline-notice">This is a local demonstration, not a protected admin panel. There are no server accounts, API keys or external database. Uploads change sample city rates only; they do not train an ML model.</div><div class="stats-grid">${stat('Recent local predictions',String(total),'From the latest 60 activity events','▦')}${stat('Local profiles','1','This browser’s workspace','♙')}${stat('Average saved estimate',average?money(average):'—','Calculated from '+history.length+' saved estimates','⌂')}${stat('Captured errors',String(errors.length),'Most recent 20 local errors','◎')}</div><div class="result-grid"><article class="card"><h2>Popular locations</h2><p class="card-subtitle">Saved predictions by city</p><div class="bar-chart">${counts.slice(0,5).map(x=>`<div class="bar-column"><span>${x.count}</span><div style="--height:${x.count?Math.max(10,x.count/Math.max(1,counts[0].count)*130):4}px"></div><small>${x.city}</small></div>`).join('')}</div></article><article class="card"><h2>Model performance</h2><p class="card-subtitle">${metrics?'Imported evaluation · user supplied':'No trained model or evaluation dataset connected.'}</p><div class="table-wrap"><table class="admin-table"><tbody>${['MAE','RMSE','R²','Accuracy'].map(k=>`<tr><td>${k}</td><td>${metrics&&metrics[k]!==undefined?esc(metrics[k]):'Not measured'}</td></tr>`).join('')}</tbody></table></div><p class="metric-note">${metrics?'Source: '+esc(metrics.source)+' · These imported metrics are not verified by DwellIQ.':'The illustrative rules engine has no measured predictive accuracy. Coverage scores are not accuracy metrics.'}</p><button class="button small" id="import-metrics" style="margin-top:14px">Import evaluation metrics</button></article></div><article class="card"><div class="card-heading"><div><h2>Sample dataset management</h2><p class="card-subtitle">Replace city rates locally with validated JSON.</p></div><div class="button-row"><label class="button small" for="dataset-upload">Import JSON ↑</label><input type="file" id="dataset-upload" accept=".json,application/json" hidden><button class="button small" id="reset-dataset">Reset rates ↺</button></div></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>City</th><th>State</th><th>Sample rate / sq.ft</th><th>YoY trend</th></tr></thead><tbody>${Object.entries(E.cities).map(([city,c])=>`<tr><td>${city}</td><td>${c.state}</td><td>₹${num(E.getRate(city))}</td><td class="positive">+${c.growth}%</td></tr>`).join('')}</tbody></table></div><p class="metric-note">Format: {"Bengaluru": 6850, "Mumbai": 18200}. Supported cities only. Rates must be numbers from 500 to 100000. Changes apply to future estimates.</p></article><div class="result-grid"><article class="card"><h2>User activity</h2>${activity.length?activity.slice(0,7).map(x=>`<div class="summary-line"><span>${date(x.date)}</span><strong>${esc(x.type)} · ${esc(x.detail)}</strong></div>`).join(''):'<p class="metric-note">Activity appears here as you generate and save estimates.</p>'}</article><article class="card"><div class="card-heading"><h2>Error monitoring</h2><button class="text-link" id="clear-errors">Clear log</button></div>${errors.length?errors.slice(0,5).map(e=>`<div class="error-log">${date(e.date)} · ${esc(e.message)}</div>`).join(''):'<p class="metric-note">No local errors recorded. Validation issues are displayed directly in the form.</p>'}</article></div>`;}
  function adminTrendCard(){
    const days=Array.from({length:adminPeriod},(_,i)=>{const d=new Date();d.setDate(d.getDate()-adminPeriod+1+i);return {key:d.toISOString().slice(0,10),label:d.toLocaleDateString('en-IN',{day:'numeric',month:'short'})};});
    const values=days.map(d=>activity.filter(a=>a.type==='Prediction'&&String(a.date).slice(0,10)===d.key).length),max=Math.max(1,...values),pts=values.map((v,i)=>[45+i*402/(adminPeriod-1),135-v/max*100]);
    const path=pts.map((p,i)=>(i?'L':'M')+p.join(',')).join(' ');
    return `<article class="card" style="margin-top:22px"><div class="card-heading"><div><h2>Prediction activity</h2><p class="card-subtitle">Actual local prediction events in the most recent 60 activity records.</p></div><div class="segment-control" aria-label="Prediction activity period">${[7,30].map(n=>`<button data-admin-period="${n}" class="${adminPeriod===n?'active':''}" aria-pressed="${adminPeriod===n}">${n}D</button>`).join('')}</div></div><div class="chart"><svg viewBox="0 0 490 165" role="img" aria-label="${values.reduce((a,b)=>a+b,0)} local predictions over ${adminPeriod} days">${[0,1,2].map(i=>`<line class="chart-grid" x1="45" y1="${35+i*50}" x2="447" y2="${35+i*50}"/><text x="15" y="${38+i*50}">${(max*(1-i/2)).toFixed(1)}</text>`).join('')}<path class="chart-line" d="${path}"/>${pts.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="3" fill="var(--green)"><title>${days[i].label}: ${values[i]} local predictions</title></circle>${i%Math.ceil(adminPeriod/6)===0||i===adminPeriod-1?`<text x="${x}" y="161" text-anchor="middle">${days[i].label}</text>`:''}`).join('')}</svg></div></article>`;
  }
  function renderAdmin(){renderAdminContent();main.insertAdjacentHTML('beforeend',adminTrendCard());}
  function modal(content){$('#modal-content').innerHTML=content;$('#modal').showModal();}
  function closeModal(){$('#modal').close();}
  function go(target){if(busy&&target==='predict')return;if(location.hash==='#'+target)renderRoute();else location.hash=target;}
  function renderRoute(){const parsed=location.hash.slice(1)||'home';route=['home','predict','result','market','simulator','history','profile','admin'].includes(parsed)?parsed:'home';$('#page-label').textContent=({home:'Overview',predict:'Predict price',result:'Your estimate',market:'Market insights',simulator:'What if?',history:'My predictions',profile:'Profile',admin:'Demo admin'})[route];document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===route||(a.dataset.nav==='predict'&&['result','simulator'].includes(route));a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});({home:renderHome,predict:renderPredict,result:renderResult,market:renderMarket,simulator:renderSimulator,history:renderHistory,profile:renderProfile,admin:renderAdmin})[route]();main.classList.remove('route-enter');void main.offsetWidth;main.classList.add('route-enter');window.scrollTo({top:0,behavior:'instant'});}
  function download(data,filename,type='application/json'){const blob=data instanceof Blob?data:new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
  function reportData(){return {brand:'DwellIQ',dataSource:'Illustrative sample data; untrained rules engine',...current,market:{city:current.property.city,...E.cities[current.property.city],rate:E.getRate(current.property.city)},comparables:comparables(current.property),disclaimer};}
  async function share(){const url=new URL(location.href);url.hash='predict';url.search='';url.searchParams.set('property',JSON.stringify(current.property));modal(`<h2 class="modal-title">Share your property details</h2><p class="modal-subtitle">This link includes the property details you entered. Recipients can recalculate the sample estimate. Review personal details before sharing.</p><label class="sr-only" for="share-url">Property details link</label><textarea class="data-input" readonly id="share-url">${esc(url.href)}</textarea><div class="button-row" style="margin-top:15px"><button class="button primary" id="copy-share">Copy link ↗</button><button class="button" id="select-share">Select link</button></div>${location.protocol==='file:'?info('This file link works only on this computer. Host the website to share across devices.'):''}`);}
  function showListing(index){let p=current.property;if(route==='market')p={...p,city:marketCity,state:E.cities[marketCity].state,locality:marketCity===p.city?p.locality:Object.keys(E.cities[marketCity].areas)[0]};const l=comparables(p)[index];modal(`<h2 class="modal-title">${esc(l.name)}</h2><p class="modal-subtitle">${esc(l.locality)}, ${esc(l.city)} · Illustrative comparable</p><img class="modal-image" src="${l.image}" alt="Sample contemporary property"><div class="stats-grid" style="grid-template-columns:1fr 1fr">${stat('Sample asking price',money(l.price),'Not an active real listing')}${stat('Price / sq.ft','₹'+num(l.rate),'Sample comparable rate')}</div><div class="summary-line"><span>Property type</span><strong>${esc(l.type)}</strong></div><div class="summary-line"><span>Bedrooms / area</span><strong>${l.bedrooms||'Land'} · ${num(l.area)} sq.ft</strong></div><div class="summary-line"><span>Illustrative distance</span><strong>${l.distance} km</strong></div>${info('Images are illustrative. Property names, asking prices and distances are synthetic samples. No booking or purchase is available.')}<button class="button primary" id="use-comparable" data-index="${index}" style="margin-top:20px">Estimate a property like this ↗</button>`);}
  function compareHistory(){const selected=[...document.querySelectorAll('.history-checkbox:checked')].map(el=>history.find(r=>r.id===el.value));if(selected.length!==2){toast('Select exactly two predictions to compare.');return;}modal(`<h2 class="modal-title">Two possibilities, side by side.</h2><p class="modal-subtitle">Saved sample estimates at their original prediction dates.</p><div class="comparison-grid">${selected.map(r=>`<div class="card"><h3>${esc(r.property.locality)}, ${esc(r.property.city)}</h3><strong>${money(r.price)}</strong><p class="metric-note">${esc(r.property.type)} · ${num(r.property.area)} sq.ft<br>${r.property.bedrooms} bedrooms · ${esc(r.property.condition)}<br>₹${num(r.perSqft)}/sq.ft<br>${r.confidence}% illustrative confidence<br>${date(r.date)}</p></div>`).join('')}</div><div class="inline-notice" style="margin-top:20px">Difference: ${money(Math.abs(selected[0].price-selected[1].price))} · ${((Math.abs(selected[0].price-selected[1].price)/selected[1].price)*100).toFixed(1)}% of the second estimate.</div>`);}
  function chat(text,user=false){const el=document.createElement('div');el.className='chat-message'+(user?' user':'');el.textContent=text;$('#chat-messages').append(el);$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight;}
  function answer(question){const q=question.toLowerCase(),r=current,p=r.property,c=E.cities[p.city];let response;
    if(/5|five|future|worth in|outlook/.test(q)){const low=r.price*1.02**5,high=r.price*1.07**5;response=`As a scenario only, annual growth of 2%–7% would put ${money(r.price)} at roughly ${money(low)}–${money(high)} in five years. These are hypothetical assumptions, not a forecast. Costs, inflation and changes in the local market can affect the outcome.`;}
    else if(/average|area|market/.test(q)){response=`Our illustrative ${p.city} city rate is ₹${num(E.getRate(p.city))}/sq.ft. The sample locality multiplier for ${p.locality} is ${(Object.hasOwn(c.areas,p.locality)?c.areas[p.locality]:1).toFixed(2)}. Your current property estimate is ₹${num(r.perSqft)}/sq.ft. These are sample figures, not current market prices.`;}
    else if(/increase|renovat|improve|value/.test(q)){response=`Condition, usable space, parking and nearby facilities affect this sample estimate. Try “What if?” to compare excellent condition, extra area or parking. Compare the estimated increase with actual improvement costs before making a decision.`;}
    else if(/negotia|overpric|asking/.test(q)){const match=q.match(/(?:₹|rs\.?|inr)?\s*(\d+(?:\.\d+)?)\s*(crore|cr|lakh|lac|l|million)?/);const asking=match?Number(match[1])*({crore:1e7,cr:1e7,lakh:1e5,lac:1e5,l:1e5,million:1e6}[match[2]]||1):null;response=asking?`An asking price of ${money(asking)} is ${asking>r.price?'above':'below'} the current sample estimate by ${money(Math.abs(asking-r.price))}. The illustrative range is ${money(r.min)}–${money(r.max)}. This alone cannot establish whether a property is overpriced. Compare recent verified sales and condition.`:`Your illustrative estimate is ${money(r.price)}, with a range of ${money(r.min)}–${money(r.max)}. Tell me an asking price (for example, “asking 95 lakh”) to compare. Verify recent sales, legal documents and repair costs before negotiating.`;}
    else if(/buy|investment|invest|should/.test(q))response=`This sample estimate cannot determine whether you should buy. Review affordability, title, condition, verified sale prices, rental demand and total ownership costs. The sample ${p.city} trend is +${c.growth}% and is illustrative, not evidence of future returns.`;
    else response=`I can explain the current ${p.locality}, ${p.city} estimate of ${money(r.price)}, compare an asking price, discuss value improvements, or show a hypothetical five-year scenario. I’m a local automated guide, not a connected AI service. Try “What is the average price in this area?”`;
    chat(response);
  }
  function openAssistant(){$('#assistant').hidden=false;$('#assistant-toggle').setAttribute('aria-expanded','true');if(!$('#chat-messages').children.length)chat('Hi, I’m your Property AI Assistant. Let’s explore the possibilities of your home. I use your current estimate and sample data to explain prices, improvements and scenarios.');$('#chat-input').focus();}
  document.addEventListener('click',async event=>{const b=event.target.closest('button,[data-route]');if(!b)return;try{
    if(b.dataset.route){go(b.dataset.route);return;}
    if(b.dataset.period){chartPeriod=b.dataset.period;route==='market'?renderMarket():renderHome();return;}
    if(b.dataset.market){marketCity=b.dataset.market;renderMarket();return;}
    if(b.dataset.adminPeriod){adminPeriod=Number(b.dataset.adminPeriod);renderAdmin();return;}
    if(b.dataset.listing!==undefined){showListing(Number(b.dataset.listing));return;}
    if(b.dataset.bookmark!==undefined){const p=route==='market'?{...current.property,city:marketCity,locality:marketCity===current.property.city?current.property.locality:Object.keys(E.cities[marketCity].areas)[0]}:current.property,l=comparables(p)[Number(b.dataset.bookmark)];bookmarks=bookmarks.includes(l.id)?bookmarks.filter(id=>id!==l.id):[...bookmarks,l.id];write('bookmarks',bookmarks);b.textContent=bookmarks.includes(l.id)?'♥':'♡';b.setAttribute('aria-pressed',String(bookmarks.includes(l.id)));b.setAttribute('aria-label',(bookmarks.includes(l.id)?'Unsave ':'Save ')+l.name);toast(bookmarks.includes(l.id)?'Sample property saved on this device.':'Property removed from saved items.');return;}
    if(b.dataset.history){current=history.find(r=>r.id===b.dataset.history);simulation=null;go('result');return;}
    if(b.dataset.delete){const id=b.dataset.delete;modal(`<h2 class="modal-title">Remove this prediction?</h2><p class="modal-subtitle">This removes the saved estimate from local history.</p><button class="button danger" id="confirm-delete" data-id="${esc(id)}">Delete prediction</button>`);return;}
    if(b.dataset.question){openAssistant();chat(b.dataset.question,true);answer(b.dataset.question);return;}
    switch(b.id){
      case 'theme-toggle':case 'profile-theme':setTheme(document.body.classList.contains('dark')?'light':'dark');if(route==='profile')renderProfile();break;
      case 'step-back':collectDraft();step=Math.max(0,step-1);renderPredict();break;
      case 'edit-property':draft={...current.property,amenities:[...current.property.amenities]};step=0;go('predict');break;
      case 'save-prediction':savePrediction(current,true);break;
      case 'pdf-report':download(window.DwellReports.pdf(reportData()),'DwellIQ-property-report.pdf','application/pdf');record('Report','PDF download');toast('PDF report downloaded.');break;
      case 'json-report':download(JSON.stringify(reportData(),null,2),'DwellIQ-property-report.json');toast('Detailed data report downloaded.');break;
      case 'share-prediction':await share();break;
      case 'copy-share':try{await navigator.clipboard.writeText($('#share-url').value);toast('Property details link copied. The estimate is recalculated on the receiving device.');}catch{$('#share-url').select();toast('Link selected. Press Ctrl+C or use your browser’s Copy action.');}break;
      case 'select-share':$('#share-url').select();toast('Link selected. Press Ctrl+C to copy.');break;
      case 'reset-simulator':simulation=null;renderSimulator();break;
      case 'save-simulation':{const r=E.predict(simulation);r.id=crypto.randomUUID();savePrediction(r,true);record('Simulation',simulation.city);break;}
      case 'compare-history':compareHistory();break;
      case 'confirm-delete':history=history.filter(r=>r.id!==b.dataset.id);write('history',history);closeModal();renderHistory();toast('Prediction removed.');break;
      case 'export-history':download(JSON.stringify(history,null,2),'DwellIQ-prediction-history.json');break;
      case 'clear-history':modal('<h2 class="modal-title">Clear your prediction history?</h2><p class="modal-subtitle">All saved estimates will be removed from this browser. You can export your history first.</p><button class="button danger" id="confirm-clear">Clear saved history</button>');break;
      case 'confirm-clear':history=[];write('history',history);closeModal();renderProfile();toast('Saved history cleared.');break;
      case 'export-dataset':download(JSON.stringify(Object.fromEntries(Object.keys(E.cities).map(c=>[c,E.getRate(c)])),null,2),'DwellIQ-sample-rates.json');break;
      case 'reset-dataset':E.resetRates();write('rates',{});renderAdmin();toast('Sample rates restored.');break;
      case 'clear-errors':errors=[];write('errors',errors);renderAdmin();break;
      case 'import-metrics':modal('<h2 class="modal-title">Import evaluation metrics</h2><p class="modal-subtitle">Paste measured results from your own evaluated model. These numbers remain user supplied and do not connect that model.</p><label for="metrics-input" class="field-label">Evaluation JSON</label><textarea class="data-input" id="metrics-input" placeholder=\'{"MAE":250000,"RMSE":400000,"R²":0.84,"Accuracy":"Not applicable","source":"My held-out test set"}\'></textarea><button class="button primary" id="save-metrics" style="margin-top:15px">Save metrics</button>');break;
      case 'save-metrics':{const m=JSON.parse($('#metrics-input').value);if(!m||typeof m.source!=='string'||!m.source.trim()||m.source.length>150||!Number.isFinite(m.MAE)||m.MAE<0||!Number.isFinite(m.RMSE)||m.RMSE<0||!Number.isFinite(m['R²'])||m['R²']>1||typeof m.Accuracy!=='string'||m.Accuracy.length>50)throw new Error('Supply nonnegative numeric MAE/RMSE, numeric R² ≤ 1, a short Accuracy description, and source.');write('metrics',m);closeModal();renderAdmin();toast('User-supplied evaluation metrics saved.');break;}
      case 'use-comparable':{let p=current.property;if(route==='market')p={...p,city:marketCity,state:E.cities[marketCity].state,locality:Object.keys(E.cities[marketCity].areas)[0]};const l=comparables(p)[Number(b.dataset.index)];draft={...p,area:l.area,builtup:Math.round(l.area*.9),carpet:Math.round(l.area*.75),bedrooms:l.bedrooms,amenities:[...p.amenities]};step=0;closeModal();go('predict');break;}
      case 'assistant-toggle':if($('#assistant').hidden)openAssistant();else{$('#assistant').hidden=true;b.setAttribute('aria-expanded','false');}break;
      case 'assistant-close':$('#assistant').hidden=true;$('#assistant-toggle').focus();break;
      case 'disclaimer-button':modal(`<h2 class="modal-title">A clearer view, with context.</h2><p class="modal-subtitle">${disclaimer}</p><p class="metric-note">This implementation uses realistic sample data and an explainable rules engine. It does not use a trained AI model, live property listings, a secure account system or verified financial data. The valuation interface can be replaced by a connected, validated model later.</p>`);break;
    }
  }catch(e){logError(e);toast(e.message||'Something went wrong. Please try again.');}});
  document.addEventListener('submit',event=>{try{if(event.target.id==='quick-form'){event.preventDefault();if(!event.target.reportValidity())return;const city=$('#quick-city').value,area=Number($('#quick-area').value);draft={...defaultProperty,city,state:E.cities[city].state,locality:Object.keys(E.cities[city].areas)[0],area,builtup:Math.round(area*.9),carpet:Math.round(area*.75),bedrooms:Number($('#quick-beds').value),amenities:[...defaultProperty.amenities]};step=0;go('predict');}
    if(event.target.id==='prediction-form'){event.preventDefault();if(!event.target.reportValidity())return;collectDraft();if(step===0){const errors=E.validate(draft).filter(e=>/country|city|State|locality|PIN/i.test(e));if(errors.length){renderPredict(errors.join(' '));return;}}if(step===1){const errors=E.validate(draft);if(errors.length){renderPredict(errors.join(' '));return;}}if(step<3){step++;renderPredict();}else generate();}
    if(event.target.id==='profile-form'){event.preventDefault();const name=$('#profile-name').value.trim();if(!name){toast('Please enter a display name.');return;}profile={...profile,name,city:$('#profile-city').value};write('profile',profile);refreshName();marketCity=profile.city;renderProfile();toast('Preferences saved.');}
    if(event.target.id==='chat-form'){event.preventDefault();const text=$('#chat-input').value.trim();if(!text)return;chat(text,true);$('#chat-input').value='';answer(text);}
  }catch(e){event.preventDefault();logError(e);toast(e.message);}});
  document.addEventListener('change',async event=>{const el=event.target;try{
    if(el.id==='market-city'){marketCity=el.value;route==='market'?renderMarket():renderHome();}
    if(el.id==='state'){collectDraft();draft.city=Object.keys(E.cities).find(c=>E.cities[c].state===draft.state);draft.locality=Object.keys(E.cities[draft.city].areas)[0];renderPredict();}
    if(el.id==='city'){collectDraft();draft.state=E.cities[draft.city].state;draft.locality=Object.keys(E.cities[draft.city].areas)[0];renderPredict();}
    if(el.id==='type'){collectDraft();if(draft.type==='Plot/Land'){Object.assign(draft,{bedrooms:0,bathrooms:0,balconies:0,builtup:0,carpet:0,floor:0,floors:0,age:0,furnishing:'Unfurnished',parking:'No'});}else if(!draft.bedrooms){Object.assign(draft,{bedrooms:2,bathrooms:2,builtup:Math.round(draft.area*.9),carpet:Math.round(draft.area*.75),floors:1});}renderPredict();}
    if(el.id==='auto-save'){profile.persist=el.checked;write('profile',profile);toast(el.checked?'New predictions will be saved automatically.':'Automatic saving turned off.');}
    if(el.closest('#sim-form'))updateSimulation();
    if(el.id==='dataset-upload'){const file=el.files[0];if(!file)return;if(file.size>50000)throw new Error('Choose a JSON rate file smaller than 50 KB.');const data=JSON.parse(await file.text());if(!data||Array.isArray(data)||typeof data!=='object'||!Object.keys(data).length)throw new Error('Upload an object containing city rates.');E.setRates(data);write('rates',data);record('Dataset','Sample rates imported');renderAdmin();toast('Sample city rates updated locally.');}
  }catch(e){logError(e);toast(e.message);}});
  document.addEventListener('input',event=>{if(event.target.closest('#sim-form')){try{updateSimulation();}catch(e){toast(e.message);}}});
  document.addEventListener('mouseover',event=>{const el=event.target.closest('[data-chart-point]');if(el){const tip=el.closest('.chart').querySelector('.chart-tip');tip.hidden=false;tip.textContent='₹'+num(el.dataset.chartPoint)+' / sq.ft · sample';}});
  document.addEventListener('mouseout',event=>{const el=event.target.closest('[data-chart-point]');if(el)el.closest('.chart').querySelector('.chart-tip').hidden=true;});
  document.addEventListener('focusin',event=>{if(event.target.dataset.chartPoint){const tip=event.target.closest('.chart').querySelector('.chart-tip');tip.hidden=false;tip.textContent='₹'+num(event.target.dataset.chartPoint)+' / sq.ft · sample';}});
  document.addEventListener('focusout',event=>{if(event.target.dataset.chartPoint)event.target.closest('.chart').querySelector('.chart-tip').hidden=true;});
  $('#modal .modal-close').addEventListener('click',closeModal);$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)closeModal();}});
  window.addEventListener('hashchange',renderRoute);window.addEventListener('error',event=>logError(event.error||event.message));window.addEventListener('unhandledrejection',event=>logError(event.reason));
  try{const shared=new URL(location.href).searchParams.get('property');if(shared){const p=JSON.parse(shared);if(E.validate(p).length)throw new Error('The shared property details are invalid.');draft=p;step=0;current=E.predict(p);toast('Shared property details loaded. Review them to generate an estimate.');}}catch(e){logError(e);toast('Unable to load the shared property details.');}
  renderRoute();
})();
